package com.crm.hr;
import com.crm.hr.service.HrStatisticsService;import com.crm.hr.repository.HrStatisticsRepository;import org.junit.jupiter.api.*;import java.util.*;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
class HrStatisticsPolicyTest {
 final HrStatisticsRepository repository=mock(HrStatisticsRepository.class);final HrStatisticsService service=new HrStatisticsService(repository);
 static HrStatisticsRepository.StatusCount count(String status,long total){return new HrStatisticsRepository.StatusCount(){public String getStatus(){return status;}public long getTotal(){return total;}};}
 @BeforeEach void setup(){org.springframework.security.core.context.SecurityContextHolder.getContext().setAuthentication(LeaveBalanceOwnershipTest.auth("ADMIN"));}
 @AfterEach void clear(){org.springframework.security.core.context.SecurityContextHolder.clearContext();}
 @Test void knownAggregatesPreserveStatusCountsAndUniqueEmployeeDays(){when(repository.leaves(any(),any())).thenReturn(List.of(count("APPROVED",3),count("PENDING",2)));when(repository.approvedEmployeeDays(any(),any())).thenReturn(7L);when(repository.trainings(any(),any())).thenReturn(List.of(count("PLANNED",4),count("COMPLETED",2)));when(repository.applications(any(),any())).thenReturn(List.of(count("RECEIVED",2)));var result=service.read(LeaveBalanceCalculationTest.FROM,LeaveBalanceCalculationTest.TO);assertEquals(3L,result.leaves().get("APPROVED"));assertEquals(7,result.approvedEmployeeDays());assertEquals(2L,result.trainings().get("COMPLETED"));assertEquals(0L,result.applications().get("REJECTED"));}
 @Test void emptyAggregatesHaveAllExplicitZeroStatuses(){var result=service.read(LeaveBalanceCalculationTest.FROM,LeaveBalanceCalculationTest.TO);assertEquals(3,result.leaves().size());assertTrue(result.leaves().values().stream().allMatch(v->v==0));assertEquals(4,result.trainings().size());}
 @Test void recruitmentUsesExclusiveNextDayBoundary(){service.read(LeaveBalanceCalculationTest.FROM,LeaveBalanceCalculationTest.TO);verify(repository).offers(LeaveBalanceCalculationTest.FROM.atStartOfDay(),LeaveBalanceCalculationTest.TO.plusDays(1).atStartOfDay());verify(repository).applications(LeaveBalanceCalculationTest.FROM.atStartOfDay(),LeaveBalanceCalculationTest.TO.plusDays(1).atStartOfDay());verifyNoMoreInteractionsAfterExpected();}
 private void verifyNoMoreInteractionsAfterExpected(){verify(repository).leaves(any(),any());verify(repository).trainings(any(),any());verify(repository).evaluations(any(),any());verify(repository).approvedEmployeeDays(any(),any());verifyNoMoreInteractions(repository);}
 @Test void unknownStatusIsAnErrorRatherThanDiscarded(){when(repository.leaves(any(),any())).thenReturn(List.of(count("INVALID",10)));assertThrows(IllegalStateException.class,()->service.read(LeaveBalanceCalculationTest.FROM,LeaveBalanceCalculationTest.TO));}
 @Test void invalidPeriodNeverQueries(){assertThrows(IllegalArgumentException.class,()->service.read(LeaveBalanceCalculationTest.TO,LeaveBalanceCalculationTest.FROM));verifyNoInteractions(repository);}
 @Test void employeeAndClientCannotReadStatistics(){for(String role:List.of("EMPLOYEE","CLIENT")){org.springframework.security.core.context.SecurityContextHolder.getContext().setAuthentication(LeaveBalanceOwnershipTest.auth(role));assertThrows(org.springframework.security.access.AccessDeniedException.class,()->service.read(LeaveBalanceCalculationTest.FROM,LeaveBalanceCalculationTest.TO));}verifyNoInteractions(repository);}
}